(()=>{const section=document.querySelector('.google-signin'),button=document.querySelector('#google-signin');if(!section||!button)return;fetch('/api/auth/providers',{cache:'no-store'}).then(async r=>{if(r.ok&&(await r.json()).google)section.hidden=false}).catch(()=>{});button.onclick=async()=>{button.disabled=true;const status=document.querySelector('.auth-status');try{const r=await fetch('/api/auth/google',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'}),data=await r.json();if(!r.ok)throw Error(data.error||'Unable to start Google sign-in.');const url=new URL(data.url);if(url.protocol!=='https:'||url.hostname!=='stnetlqzgmuaqormvnvg.supabase.co'||url.pathname!=='/auth/v1/authorize')throw Error('Unable to open Google sign-in.');location.assign(url.href)}catch(e){status.hidden=false;status.textContent=e.message;status.focus();button.disabled=false}}})();
